// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 blockTimestamp, uint256 blockNumber) public {
        vm.assume(value != 10 ether);
        vm.assume(blockTimestamp > 0);

        vm.warp(blockTimestamp);
        vm.roll(blockNumber);

        uint256 pastBlockTimeBefore = c.pastBlockTime();

        (bool success, ) = address(c).call{value: value}("");

        uint256 pastBlockTimeAfter = c.pastBlockTime();

        assertTrue(!success || pastBlockTimeAfter == pastBlockTimeBefore);
    }
}

